/// Свежие данные дашборда: курс валют и лента новостей.
class DashboardData {
  const DashboardData({required this.currencies, required this.news});

  final List<CurrencyModel> currencies;
  final List<NewsModel> news;
}

class DashboardPage extends StatefulWidget {
  const DashboardPage({super.key});

  /// Запрашивает свежий курс валют и свежую ленту новостей параллельно.
  static Future<DashboardData> load(BuildContext context) {
    final CurrencyRepository currencyRepository = context.read<CurrencyRepository>();
    final NewsRepository newsRepository = context.read<NewsRepository>();

    final Future<CurrencyPage> currencyFuture = currencyRepository.fetchRates(const CurrencyPageRequest());
    final Future<List<NewsModel>> newsFuture = newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true));

