      final CurrencyPage currencyPage = results[0] as CurrencyPage;
      final List<NewsModel> news = results[1] as List<NewsModel>;

      return DashboardData(currencies: currencyPage.items, news: news);
    });
  }

  @override
  State<DashboardPage> createState() => _DashboardPageState();
}

class _DashboardPageState extends State<DashboardPage> {
  late Future<DashboardData> _dashboardFuture;

  @override
  void initState() {
    super.initState();
    _dashboardFuture = DashboardPage.load(context);
  }

  void _refresh() {
    setState(() {
      _dashboardFuture = DashboardPage.load(context);
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text(context.loc.dashboard),
