            onPressed: _refresh,
            icon: const Icon(Icons.refresh),
            tooltip: context.loc.refresh,
          ),
        ],
      ),
      body: FutureBuilder<DashboardData>(
        future: _dashboardFuture,
        builder: (BuildContext context, AsyncSnapshot<DashboardData> snapshot) {
          final DashboardData? data = snapshot.data;
          if (data == null) return const Center(child: CircularProgressIndicator());

          return ListView(
            padding: const EdgeInsets.fromLTRB(22, 16, 22, 40),
            children: [
              _SectionTitle(title: context.loc.currencyRate),
              for (int index = 0; index < data.currencies.length; index++)
                Padding(
                  key: ValueKey(data.currencies[index].id),
                  padding: EdgeInsets.only(top: index == 0 ? 12 : 10),
                  child: CurrencyCard(model: data.currencies[index]),
                ),
              Padding(
                padding: const EdgeInsets.only(top: 24),
                child: _SectionTitle(title: context.loc.news),
              ),
              for (int index = 0; index < data.news.length; index++)
                Padding(
