}

class _SectionTitle extends StatelessWidget {
  const _SectionTitle({required this.title});

  final String title;

  @override
  Widget build(BuildContext context) {
    return Text(
      title,
      style: context.fonts.semiBold12.copyWith(color: context.colors.blueDepression),
    );
  }
}

