8: 
9: /// Свежие данные дашборда: курс валют и лента новостей.
10: class DashboardData {
11:   const DashboardData({required this.currencies, required this.news});
12: 
13:   final List<CurrencyModel> currencies;
14:   final List<NewsModel> news;
15: }
16: 
17: class DashboardPage extends StatefulWidget {
18:   const DashboardPage({super.key});
19: 
20:   /// Запрашивает свежий курс валют и свежую ленту новостей параллельно.
21:   static Future<DashboardData> load(BuildContext context) {
22:     final CurrencyRepository currencyRepository = context.read<CurrencyRepository>();
23:     final NewsRepository newsRepository = context.read<NewsRepository>();
24: 
25:     final Future<CurrencyPage> currencyFuture = currencyRepository.fetchRates(const CurrencyPageRequest());
26:     final Future<List<NewsModel>> newsFuture = newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true));
27: 
28:     return Future.wait(<Future<Object>>[currencyFuture, newsFuture]).then((List<Object> results) {
29:       final CurrencyPage currencyPage = results[0] as CurrencyPage;
30:       final List<NewsModel> news = results[1] as List<NewsModel>;
31: 
32:       return DashboardData(currencies: currencyPage.items, news: news);
33:     });
34:   }
35: 
36:   @override
37:   State<DashboardPage> createState() => _DashboardPageState();
38: }
39: 
40: class _DashboardPageState extends State<DashboardPage> {
41:   late Future<DashboardData> _dashboardFuture;
42: 
43:   bool _isLoading = true;
44: 
45:   @override
46:   void initState() {
47:     super.initState();
48:     _load();
49:   }
50: 
51:   void _load() {
52:     setState(() => _isLoading = true);
53: 
54:     _dashboardFuture = DashboardPage.load(context).whenComplete(() {
55:       if (mounted) setState(() => _isLoading = false);
56:     });
57:   }
58: 
59:   void _refresh() {
60:     _load();
61:   }
62: 
63:   @override
64:   Widget build(BuildContext context) {
65:     return Scaffold(
66:       appBar: AppBar(
67:         title: Text(context.loc.dashboard),
68:         actions: [
69:           IconButton(
70:             onPressed: _refresh,
71:             icon: const Icon(Icons.refresh),
72:             tooltip: context.loc.refresh,
73:           ),
74:         ],
75:       ),
76:       body: FutureBuilder<DashboardData>(
77:         future: _dashboardFuture,
78:         builder: (BuildContext context, AsyncSnapshot<DashboardData> snapshot) {
79:           final DashboardData? data = snapshot.data;
80:           if (_isLoading || data == null) return const Center(child: CircularProgressIndicator());
81: 
82:           return ListView(
83:             padding: const EdgeInsets.fromLTRB(22, 16, 22, 40),
84:             children: [
85:               _SectionTitle(title: context.loc.currencyRate),
86:               for (int index = 0; index < data.currencies.length; index++)
87:                 Padding(
88:                   key: ValueKey(data.currencies[index].id),
89:                   padding: EdgeInsets.only(top: index == 0 ? 12 : 10),
90:                   child: CurrencyCard(model: data.currencies[index]),
91:                 ),
92:               Padding(
93:                 padding: const EdgeInsets.only(top: 24),
94:                 child: _SectionTitle(title: context.loc.news),
95:               ),
96:               for (int index = 0; index < data.news.length; index++)
97:                 Padding(
98:                   key: ValueKey(data.news[index].link),
99:                   padding: EdgeInsets.only(top: index == 0 ? 12 : 16),
100:                   child: NewsCard(model: data.news[index]),
101:                 ),
102:             ],
103:           );
104:         },
105:       ),
106:     );
107:   }
108: }
109: 
110: class _SectionTitle extends StatelessWidget {
111:   const _SectionTitle({required this.title});
112: 
113:   final String title;
114: 
115:   @override
116:   Widget build(BuildContext context) {
117:     return Text(
118:       title,
119:       style: context.fonts.semiBold12.copyWith(color: context.colors.blueDepression),
120:     );
121:   }
122: }

